def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1

    last_my, last_opp = history[-1]

    if n == 99:
        return 'D'

    if n >= 95:
        if opp_d == 0 and my_d > 0:
            return 'D'
        if opp_d > 0:
            recent_opp = [b for a, b in history[-5:]]
            if recent_opp.count('D') >= 2:
                return 'D'
            if my_d > 0:
                last_my_d_idx = -1
                for i in range(n-1, -1, -1):
                    if history[i][0] == 'D':
                        last_my_d_idx = i
                        break
                if last_my_d_idx != -1 and last_my_d_idx < n-1:
                    if history[last_my_d_idx+1][1] == 'C':
                        return 'D'
            return 'C'
        return 'C'

    if last_opp == 'D':
        if opp_d <= 2 or opp_d * 10 < n:
            if rng.random() < 0.2:
                return 'C'
        recent_opp = [b for a, b in history[-3:]]
        if recent_opp.count('D') >= 2:
            return 'D'
        return 'D' if rng.random() < 0.85 else 'C'
    else:
        if opp_d == 0 and my_d > 0:
            return 'D' if rng.random() < 0.8 else 'C'
        if last_my == 'D':
            return 'C'
        if opp_d * 3 > n:
            return 'D' if rng.random() < 0.3 else 'C'
        run_my_c = 0
        for a, b in reversed(history):
            if a == 'C':
                run_my_c += 1
            else:
                break
        run_opp_c = 0
        for a, b in reversed(history):
            if b == 'C':
                run_opp_c += 1
            else:
                break
        if run_my_c >= 6 and run_opp_c >= 6:
            if my_d == 0:
                if rng.random() < 0.05:
                    return 'D'
            else:
                retaliations = 0
                for i in range(n-1):
                    if history[i][0] == 'D' and history[i+1][1] == 'D':
                        retaliations += 1
                if retaliations * 2 < my_d:
                    if rng.random() < 0.2:
                        return 'D'
                else:
                    if rng.random() < 0.05:
                        return 'D'
        return 'C'
